function isOn(entityId) {
    return states[entityId] && states[entityId].state === "on";
}

function timeToMinutes(entityId) {
    const entity = states[entityId];

    if (!entity || typeof entity.state !== "string") {
        return null;
    }

    const match = entity.state.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);

    if (!match) {
        return null;
    }

    const hours = Number(match[1]);
    const minutes = Number(match[2]);

    if (
        !Number.isInteger(hours) ||
        !Number.isInteger(minutes) ||
        hours < 0 ||
        hours > 23 ||
        minutes < 0 ||
        minutes > 59
    ) {
        return null;
    }

    return (hours * 60) + minutes;
}

function formatMinutes(value) {
    if (value === 1440) {
        return "24:00";
    }

    const wrapped = ((value % 1440) + 1440) % 1440;
    const hours = Math.floor(wrapped / 60);
    const minutes = wrapped % 60;

    return (
        `${String(hours).padStart(2, "0")}:` +
        `${String(minutes).padStart(2, "0")}`
    );
}

function buildSegments(definitions) {
    const segments = [];

    for (const period of definitions) {

        if (!isOn(period.enable)) {
            continue;
        }

        const start = timeToMinutes(period.start);
        const end = timeToMinutes(period.end);

        if (start === null || end === null) {
            continue;
        }

        if (start === end) {
            segments.push({
                name: period.name,
                start: 0,
                end: 1440
            });

            continue;
        }

        if (end > start) {
            segments.push({
                name: period.name,
                start,
                end
            });
        } else {
            segments.push({
                name: period.name,
                start,
                end: 1440
            });

            segments.push({
                name: period.name,
                start: 0,
                end
            });
        }
    }

    segments.sort((a, b) =>
        a.start - b.start ||
        a.end - b.end ||
        a.name.localeCompare(b.name)
    );

    return segments;
}

function validateTimeline(definitions, timelineName) {
    const segments = buildSegments(definitions);

    let firstOverlap = null;

    for (let i = 0; i < segments.length; i++) {
        for (let j = i + 1; j < segments.length; j++) {
            const a = segments[i];
            const b = segments[j];

            if (b.start >= a.end) {
                break;
            }

            if (a.name === b.name) {
                continue;
            }

            const overlapStart = Math.max(a.start, b.start);
            const overlapEnd = Math.min(a.end, b.end);

            if (overlapStart < overlapEnd) {
                const candidate = {
                    a: a.name,
                    b: b.name,
                    start: overlapStart,
                    end: overlapEnd
                };

                if (
                    firstOverlap === null ||
                    candidate.start < firstOverlap.start ||
                    (
                        candidate.start === firstOverlap.start &&
                        candidate.end < firstOverlap.end
                    )
                ) {
                    firstOverlap = candidate;
                }
            }
        }
    }

    if (firstOverlap) {
        return {
            shortMessage:
                `❌ ${firstOverlap.a} overlaps ${firstOverlap.b} ` +
                `from ${formatMinutes(firstOverlap.start)} ` +
                `to ${formatMinutes(firstOverlap.end)}`,

            notificationMessage:
                `Validation failed: ${firstOverlap.a} overlaps ` +
                `${firstOverlap.b} from ` +
                `${formatMinutes(firstOverlap.start)} to ` +
                `${formatMinutes(firstOverlap.end)}.`
        };
    }

    let coveredUntil = 0;

    for (const segment of segments) {
        if (segment.start > coveredUntil) {
            return {
                shortMessage:
                    `❌ Missing ${timelineName.toLowerCase()} tariff period ` +
                    `from ${formatMinutes(coveredUntil)} ` +
                    `to ${formatMinutes(segment.start)}`,

                notificationMessage:
                    `Validation failed: No ${timelineName.toLowerCase()} ` +
                    `tariff period covers ${formatMinutes(coveredUntil)} ` +
                    `to ${formatMinutes(segment.start)}.`
            };
        }

        if (segment.end > coveredUntil) {
            coveredUntil = segment.end;
        }
    }

    if (coveredUntil < 1440) {
        return {
            shortMessage:
                `❌ Missing ${timelineName.toLowerCase()} tariff period ` +
                `from ${formatMinutes(coveredUntil)} to 24:00`,

            notificationMessage:
                `Validation failed: No ${timelineName.toLowerCase()} ` +
                `tariff period covers ${formatMinutes(coveredUntil)} ` +
                `to 24:00.`
        };
    }

    return null;
}

