async function runVerify(msg) {
    const verify = msg.verify;

    if (!verify || !verify.id) {
        node.error("Missing msg.verify", msg);
        return;
    }

    const id = verify.id;

    const latestToken = flow.get(`verify_latest_${id}`);

    if (latestToken !== verify.token) {
        node.status({
            fill: "grey",
            shape: "ring",
            text: `${id}: stale stopped`
        });
        return;
    }

    const delayMs = Number(verify.delay_ms ?? 30000);

    setTimeout(async () => {
        try {
            const haStates = global.get("homeassistant.homeAssistant.states");

            if (!haStates) {
                node.error("HA states unavailable", msg);
                return;
            }

            const actualState = haStates[verify.actual_entity];

            if (!actualState) {
                node.error(`Entity not found: ${verify.actual_entity}`, msg);
                return;
            }

            const actual = actualState.state;

            let verified = false;

            switch (verify.comparator) {
                case "numeric_tolerance": {
                    const a = Number(actual);
                    const t = Number(verify.target);

                    if (!Number.isFinite(a) || !Number.isFinite(t)) {
                        node.error(`${id}: invalid numeric comparison. actual=${actual}, target=${verify.target}`, msg);
                        return;
                    }

                    verified = Math.abs(a - t) <= Number(verify.tolerance || 0);
                    break;
                }

                case "equals":
                    verified =
                        String(actual).toLowerCase() ===
                        String(verify.target).toLowerCase();
                    break;

                default:
                    node.error(`${id}: unknown comparator ${verify.comparator}`, msg);
                    return;
            }

            if (verified) {
                msg.verify.result = "verified";
                msg.verify.actual = actual;

                node.status({
                    fill: "green",
                    shape: "dot",
                    text: `${id}: verified`
                });

                node.send([msg, null, null]);
                return;
            }

            if (Number(verify.retry_count || 0) >= Number(verify.max_retries || 3)) {
                msg.verify.result = "failed";
                msg.verify.actual = actual;

                node.status({
                    fill: "red",
                    shape: "ring",
                    text: `${id}: failed`
                });

                node.send([null, null, msg]);
                return;
            }

            verify.retry_count = Number(verify.retry_count || 0) + 1;

            node.status({
                fill: "yellow",
                shape: "dot",
                text: `${id}: retry ${verify.retry_count}/${verify.max_retries}`
            });

            const token = env.get("SUPERVISOR_TOKEN");

            for (const call of verify.retry.calls) {
                const body = JSON.stringify(call.data);
                await new Promise((resolve, reject) => {
                    const options = {
                        hostname: "supervisor",
                        port: 80,
                        path: `/core/api/services/${call.domain}/${call.service}`,
                        method: "POST",
                        headers: {
                            "Authorization": `Bearer ${token}`,
                            "Content-Type": "application/json",
                            "Content-Length": Buffer.byteLength(body)
                        }
                    };

                    const req = http.request(options, (res) => {
                        let data = "";
                        res.on("data", chunk => data += chunk);
                        res.on("end", () => {
                            //node.warn(`${call.domain}.${call.service} status: ${res.statusCode}`);
                            if (res.statusCode >= 200 && res.statusCode < 300) {
                                resolve(data);
                            } else {
                                reject(new Error(`HA API error ${res.statusCode}: ${data}`));
                            }
                        });
                    });

                    req.on("error", reject);
                    req.write(body);
                    req.end();
                });
            }

            node.send([null, msg, null]);
            runVerify(RED.util.cloneMessage(msg));

        } catch (err) {
            node.error(err.message || err, msg);
        }
    }, delayMs);
}

