function fnv1a32(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return ("00000000" + h.toString(16)).slice(-8);
}

const md = (msg.markdown ?? "").toString();
if (!md.trim()) return null;

msg.current_hash = fnv1a32(md);
return msg;

const attrs = msg.payload?.attributes;

if (!attrs) {
  node.warn("General: sensor has no attributes (cannot mark read)");
  msg.statusCode = 200;
  msg.payload = "no attrs";
  return [null, msg];
}

const current_hash = attrs.current_hash;
if (!current_hash) {
  node.warn("General: no current_hash (cannot mark read)");
  const resp = msg;
  resp.statusCode = 200;
  resp.payload = "no current_hash";
  return [null, resp];
}

msg.version = attrs.version;
msg.markdown = attrs.md;
msg.url = attrs.url;
msg.updated = new Date().toISOString();

msg.current_hash = current_hash;
msg.last_read_hash = current_hash;

const resp = msg;
resp.statusCode = 200;
resp.payload = "ok";

return [msg, resp];

const markdown = msg.markdown;
const url = msg.url;
const updated = msg.updated;
const current_hash = msg.current_hash;

const last_read_hash = msg.last_read_hash ?? null;

const out1 = {
  payload: {
    topic: "energymanager/changelog/state",
    payload: "changelog",
    retain: true,
    qos: 0
  }
};

const out2 = {
  payload: {
    topic: "energymanager/changelog/attrs",
    payload: JSON.stringify({
      updated,
      url,
      md: markdown,
      current_hash,
      last_read_hash
    }),
    retain: true,
    qos: 0
  }
};

return [out1, out2];

const allowedBranches = ["main", "early", "test", "development"];
const branchState = global.get("homeassistant")
    ?.homeAssistant
    ?.states
    ?.["input_select.em_update_branch"]
    ?.state;

const branch = allowedBranches.includes(branchState) ? branchState : "main";

msg.branch = branch;
msg.url = `https://raw.githubusercontent.com/ha-energymanager/ha-energymanager/refs/heads/${branch}/changelog.md`;

return msg;

const code = Number(msg.statusCode);

if (code !== 200) {
    node.warn(`Changelog: HTTP ${code} for ${msg.url} (not publishing; keeping retained)`);
    return null;
}

const md = (msg.payload ?? "").toString();

if (!md.trim()) {
    node.warn(`Changelog: empty body for ${msg.url} (not publishing)`);
    return null;
}

msg.markdown = md;
msg.updated = new Date().toISOString();

return msg;

